import { BrowserRouter, Routes, Route } from "react-router-dom";
import Home from "./components/publicHomepage";
import Login from "./components/login";
import './App.css';
import Signup from "./components/signup";

import EditorPage from "./components/manaco-editor";
import LevelsPage from "./components/displayLevel";
import ProtectedRoute from "./protect/ProtectedRoute";

function App() {
  return (
    <BrowserRouter>
      <Routes>

        {/* Public */}
        <Route path="/" element={<Home />} />
        <Route path="/login" element={<Login />} />
          <Route path="/displayLevel" 

          element={  <ProtectedRoute>
              <LevelsPage />
            </ProtectedRoute>} />

        {/* Protected */}
        <Route
          path="/manaco-editor/:level"
          element={
            <ProtectedRoute>
              <EditorPage />
            </ProtectedRoute>
          }
        />

        {/* Fallback */}
        <Route path="*" element={<Home />} />

      </Routes>
    </BrowserRouter>
  );
}

export default App;
